update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(176,null::text,$$Exame a qualquer tempo$$,$$Em qualquer tempo, ainda no decorrer do prazo mínimo de duração da medida de segurança, o juiz da execução pode, diante de requerimento fundamentado do Ministério Público ou do interessado, seu procurador ou defensor, ordenar o exame para verificar a cessação da periculosidade, procedendo-se nos termos do artigo anterior.$$),
(177,null,$$Exames sucessivos$$,$$Nos exames sucessivos para verificar a cessação da periculosidade, observa-se, no que for aplicável, o disposto no artigo anterior.$$),
(178,null,$$Desinternação ou liberação$$,$$Nas hipóteses de desinternação ou de liberação (artigo 97, § 3º, do Código Penal), aplica-se o disposto nos artigos 132 e 133 da Lei.$$),
(179,null,$$Ordem de desinternação ou liberação$$,$$Transitada em julgado a sentença, o juiz expede ordem para a desinternação ou a liberação.$$),
(180,null,$$Conversão da pena privativa em restritiva de direitos$$,$$A pena privativa de liberdade não superior a 2 (dois) anos pode ser convertida em restritiva de direitos, desde que o condenado a esteja cumprindo em regime aberto (inciso I), tenha cumprido pelo menos 1/4 (um quarto) da pena (inciso II) e os antecedentes e a personalidade indiquem ser a conversão recomendável (inciso III).$$),
(181,null,$$Conversão da pena restritiva de direitos em privativa de liberdade$$,$$A pena restritiva de direitos é convertida em privativa de liberdade nas hipóteses e na forma do artigo 45 e seus incisos do Código Penal. A prestação de serviços à comunidade é convertida quando o condenado não for encontrado ou desatender a intimação por edital, não comparecer ou recusar-se injustificadamente ao serviço, praticar falta grave ou sofrer condenação por outro crime à pena privativa de liberdade não suspensa (§ 1º, a a e). Os §§ 2º e 3º tratam da conversão da limitação de fim de semana e da interdição temporária de direitos.$$),
(183,null,$$Superveniência de doença mental$$,$$Quando, no curso da execução da pena privativa de liberdade, sobrevier doença mental ou perturbação da saúde mental, o juiz, de ofício, a requerimento do Ministério Público, da Defensoria Pública ou da autoridade administrativa, pode determinar a substituição da pena por medida de segurança.$$),
(184,null,$$Conversão do tratamento ambulatorial em internação$$,$$O tratamento ambulatorial pode ser convertido em internação se o agente revelar incompatibilidade com a medida. Nessa hipótese, o prazo mínimo de internação é de 1 (um) ano (parágrafo único).$$),
(185,null,$$Excesso ou desvio de execução$$,$$Há excesso ou desvio de execução sempre que algum ato for praticado além dos limites fixados na sentença, em normas legais ou regulamentares.$$),
(186,null,$$Legitimados para o incidente de excesso ou desvio$$,$$Podem suscitar o incidente de excesso ou desvio de execução o Ministério Público (inciso I), o Conselho Penitenciário (inciso II), o sentenciado (inciso III) e qualquer dos demais órgãos da execução penal (inciso IV).$$),
(187,null,$$Anistia$$,$$Concedida a anistia, o juiz, de ofício, a requerimento do interessado ou do Ministério Público, por proposta da autoridade administrativa ou do Conselho Penitenciário, declara extinta a punibilidade.$$),
(188,null,$$Indulto individual$$,$$O indulto individual pode ser provocado por petição do condenado, por iniciativa do Ministério Público, do Conselho Penitenciário ou da autoridade administrativa.$$),
(189,null,$$Petição de indulto$$,$$A petição de indulto, acompanhada dos documentos que a instruírem, é entregue ao Conselho Penitenciário, para elaboração de parecer e posterior encaminhamento ao Ministério da Justiça.$$),
(190,null,$$Relatório do Conselho Penitenciário$$,$$O Conselho Penitenciário, à vista dos autos do processo e do prontuário, promove as diligências que entender necessárias e faz, em relatório, a narração do ilícito penal e dos fundamentos da sentença condenatória, a exposição dos antecedentes do condenado e do procedimento deste depois da prisão, emitindo parecer sobre o mérito do pedido e esclarecendo qualquer formalidade ou circunstância omitida na petição.$$),
(191,null,$$Despacho do Presidente da República$$,$$Processada no Ministério da Justiça com documentos e o relatório do Conselho Penitenciário, a petição é submetida a despacho do Presidente da República, a quem são presentes os autos do processo ou a certidão de qualquer de suas peças, se ele o determinar.$$),
(192,null,$$Efeitos do indulto concedido$$,$$Concedido o indulto e anexada aos autos cópia do decreto, o juiz declara extinta a pena ou ajusta a execução aos termos do decreto, no caso de comutação.$$),
(193,null,$$Indulto coletivo$$,$$Se o sentenciado for beneficiado por indulto coletivo, o juiz, de ofício, a requerimento do interessado, do Ministério Público, ou por iniciativa do Conselho Penitenciário ou da autoridade administrativa, providencia de acordo com o artigo anterior.$$),
(194,null,$$Procedimento judicial$$,$$O procedimento correspondente às situações previstas na Lei é judicial, desenvolvendo-se perante o juízo da execução.$$),
(195,null,$$Início do procedimento judicial$$,$$O procedimento judicial inicia-se de ofício, a requerimento do Ministério Público, do interessado, de quem o represente, de seu cônjuge, parente ou descendente, mediante proposta do Conselho Penitenciário ou, ainda, da autoridade administrativa.$$),
(196,null,$$Trâmite da portaria ou petição$$,$$A portaria ou petição é autuada, ouvindo-se em 3 (três) dias o condenado e o Ministério Público, quando não figurem como requerentes. Sendo desnecessária a produção de prova, o juiz decide de plano, em igual prazo (§ 1º); se entender indispensável prova pericial ou oral, a ordena e decide após sua produção ou na audiência designada (§ 2º).$$),
(197,null,$$Agravo em execução$$,$$Das decisões proferidas pelo juiz cabe recurso de agravo, sem efeito suspensivo.$$),
(198,null,$$Vedação de divulgação$$,$$É defesa ao integrante dos órgãos da execução penal, e ao servidor, a divulgação de ocorrência que perturbe a segurança e a disciplina dos estabelecimentos, bem como exponha o preso a inconveniente notoriedade, durante o cumprimento da pena.$$),
(199,null,$$Emprego de algemas$$,$$O emprego de algemas é disciplinado por decreto federal.$$),
(200,null,$$Condenado por crime político$$,$$O condenado por crime político não está obrigado ao trabalho.$$),
(201,null,$$Prisão civil e administrativa$$,$$Na falta de estabelecimento adequado, o cumprimento da prisão civil e da prisão administrativa efetiva-se em seção especial da Cadeia Pública.$$),
(202,null,$$Sigilo da condenação cumprida$$,$$Cumprida ou extinta a pena, não constam da folha corrida, atestados ou certidões fornecidas por autoridade policial ou por auxiliares da Justiça qualquer notícia ou referência à condenação, salvo para instruir processo pela prática de nova infração penal ou outros casos expressos em lei.$$),
(203,null,$$Normas complementares e adaptação$$,$$No prazo de 6 (seis) meses, a contar da publicação da Lei, seriam editadas as normas complementares ou regulamentares necessárias à eficácia dos dispositivos não auto-aplicáveis. Os parágrafos tratam da adaptação, construção e equipamento de estabelecimentos e serviços penais pelas Unidades Federativas em convênio com o Ministério da Justiça (§ 1º), da aquisição ou desapropriação de prédios para casas de albergados (§ 2º), da ampliação do prazo pelo Conselho Nacional de Política Criminal e Penitenciária (§ 3º) e da suspensão de ajuda financeira da União em caso de descumprimento injustificado (§ 4º).$$),
(204,null,$$Vigência$$,$$A Lei entra em vigor concomitantemente com a lei de reforma da Parte Geral do Código Penal, revogadas as disposições em contrário, especialmente a Lei nº 3.274, de 2 de outubro de 1957.$$)
) as v(n,t,c,a) where l.codigo='lep' and l.numero=v.n and l.titulo is not distinct from v.t and l.inciso is null and l.paragrafo is null and l.texto like 'Art%' and l.vigente;